@push('script')<script>const types=document.querySelectorAll('input[name="order_type"]');const refresh=()=>{const type=document.querySelector('input[name="order_type"]:checked')?.value;document.querySelector('input[name="room_number"]').closest('label').style.display=type==='room_service'?'grid':'none';document.querySelector('textarea[name="delivery_address"]').closest('label').style.display=type==='delivery'?'grid':'none';};types.forEach(x=>x.addEventListener('change',refresh));refresh();</script>@endpush
